class Command(BaseCommand):
    help = 'Populate Story 3: Vasudeva’s Truthfulness and the Slaying of the Six Sons across 7 languages'

    def handle(self, *args, **options):
        topic = StoryMainTopic.objects.get(id=2)
        slug = 'krishna-pastimes-vasudevas-truthfulness-and-the-slaying-of-the-six-sons'
        image_path = 'stories/images/vasudeva_kirtiman_kamsa.jpg'

        story, created = Story.objects.get_or_create(
            slug=slug,
            defaults={
                'topic': topic,
                'order': 2,
                'imagePath': image_path,
            }
        )
        if not created:
            story.topic = topic
            story.order = 2
            story.imagePath = image_path
            story.save()

        articles = {
            'en': ('Krishna Pastimes', "Vasudeva's Truthfulness and the Slaying of the Six Sons", ARTICLE_EN),
            'ta': ('கிருஷ்ண லீலைகள்', "வசுதேவரின் சத்தியமும் ஆறு குழந்தைகளின் கொடூர வதமும்", ARTICLE_TA),
            'hi': ('श्रीकृष्ण की दिव्य लीलाएँ', "वसुदेव जी की सत्यनिष्ठा एवं छह पुत्रों का वध", ARTICLE_HI),
            'ml': ('ശ്രീകൃഷ്ണ ലീലകൾ', "വസുദേവരുടെ സത്യസന്ധതയും ആറ് പുത്രന്മാരുടെ നിഗ്രഹവും", ARTICLE_ML),
            'bn': ('শ্রীকৃষ্ণের দিব্য লীলা', "বসুদেবের সত্যনিষ্ঠা ও ছয় পুত্রের নির্মম বধ", ARTICLE_BN),
            'te': ('శ్రీకృష్ణుని దివ్య లీలలు', "వసుదేవుని సత్యనిష్ఠ మరియు ఆరుగురు పుత్రుల వధ", ARTICLE_TE),
            'kn': ('ಶ್ರೀಕೃಷ್ಣ ಲೀಲೆಗಳು', "ವಸುದೇವರ ಸತ್ಯನಿಷ್ಠೆ ಮತ್ತು ಆರು ಮಕ್ಕಳ ಸಂಹಾರ", ARTICLE_KN),
        }

        created_trans = {}
        for lang, (main_topic, sub_topic, text) in articles.items():
            tr, _ = StoryTranslation.objects.get_or_create(
                story=story,
                language_code=lang,
                defaults={
                    'mainTopic': main_topic,
                    'subTopic': sub_topic,
                    'article': text,
                }
            )
            tr.mainTopic = main_topic
            tr.subTopic = sub_topic
            tr.article = text
            tr.save()
            created_trans[lang] = tr
            self.stdout.write(f"Saved {lang} translation.")

        # Save questions across all 7 languages
        for idx, q_data in enumerate(QUESTIONS_DATA, start=1):
            for lang in ['en', 'ta', 'hi', 'ml', 'bn', 'te', 'kn']:
                tr = created_trans[lang]
                q_text, opts = q_data[lang]

                q, _ = StoryQuestion.objects.get_or_create(
                    translation=tr,
                    order=idx,
                    defaults={'question_text': q_text}
                )
                q.question_text = q_text
                q.save()

                q.options.all().delete()
                for opt_idx, (opt_text, is_corr) in enumerate(opts, start=1):
                    StoryQuestionOption.objects.create(
                        question=q,
                        order=opt_idx,
                        option_text=opt_text,
                        is_correct=is_corr
                    )

        self.stdout.write(self.style.SUCCESS(f"Successfully populated Story 3 (ID: {story.id}) across all 7 languages with 10 MCQs each!"))
